<?php require_once __DIR__.'/../core.php'; require_once __DIR__.'/auth.php'; $items=data_list('documents'); if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['delete'])){$id=(int)$_POST['delete'];$items=array_values(array_filter($items,fn($x)=>($x['id']??0)!=$id));}else{$new=['id'=>time(),'date'=>now()];$new['client']=$_POST['client']??'';$new['title']=$_POST['title']??'';$new['type']=$_POST['type']??'';$new['file_url']=$_POST['file_url']??'';$new['status']=$_POST['status']??'';$new['description']=$_POST['description']??'';$items[]=$new;} data_save('documents',$items); header('Location:/admin/documents.php'); exit;} ?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/style.css?v=110"></head><body><div class="admin-layout"><?php include __DIR__.'/sidebar.php'; ?><main class="admin-main"><h1>Documents clients</h1><form class="card" method="post"><div class="form-grid"><label>Client<input type="text" name="client"></label><label>Document<input type="text" name="title"></label><label>Type<input type="text" name="type"></label><label>Lien fichier<input type="text" name="file_url"></label><label>Statut<select name="status"><option>En attente</option><option>Validé</option><option>Refusé</option></select></label><label class="full">Description<textarea name="description" rows="4"></textarea></label></div><button class="btn btn-primary">Ajouter</button></form><table class="table"><tr><th>Client</th><th>Document</th><th>Type</th><th>Lien fichier</th><th>Statut</th><th>Description</th><th></th></tr><?php foreach(array_reverse($items) as $item): ?><tr><td><?=e($item['client']??'')?></td><td><?=e($item['title']??'')?></td><td><?=e($item['type']??'')?></td><td><?=e($item['file_url']??'')?></td><td><?=e($item['status']??'')?></td><td><?=e($item['description']??'')?></td><td><form method="post"><button class="btn danger" name="delete" value="<?=e($item['id'])?>">Supprimer</button></form></td></tr><?php endforeach; ?></table></main></div><script>
(function(){const saved=localStorage.getItem('geah_theme')||'dark';if(saved==='light')document.body.classList.add('light-mode');function ready(){const btn=document.createElement('button');btn.className='theme-toggle';function label(){btn.textContent=document.body.classList.contains('light-mode')?'🌙 Mode sombre':'☀️ Mode clair'}btn.onclick=function(){document.body.classList.toggle('light-mode');localStorage.setItem('geah_theme',document.body.classList.contains('light-mode')?'light':'dark');label()};label();document.body.appendChild(btn)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready);else ready();})();
</script></body></html>